  if(!hit){var ct=L.filter(function(t){var x=trNorm(t.title);return x&&(x.indexOf(q)>=0||q.indexOf(x)>=0)});if(ct.length>1)return{ok:false,label:LB,mode:'read',reason:'「'+String(op.title).slice(0,20)+'」对上了好几篇：'+ls(ct)+'。写全标题再读一次'};hit=ct[0]||null}
  if(!hit)return{ok:false,label:LB,mode:'read',reason:'没找到《'+String(op.title).slice(0,20)+'》。你写过的：'+ls(L)};
