ticketOf=async function(cfg,op){
  var mid=String(op&&op._userMessageId||'');if(!mid)return null;
  var row=null;try{row=await dbGet('apiSettings','map_ticket_'+mid)}catch(e){}
  if(!row||row.status!=='issued'||String(row.friendId||'')!==String(cfg&&cfg.id||'')||String(row.threadId||'')!==String(op&&op._threadId||''))return null;
  row.status='running';try{await dbPut('apiSettings',row)}catch(e){return null}
  return{play:row.play,m:{id:mid,friendId:row.friendId,play:row.play},ticketId:mid}
};
pendTrip=async function(cfg,T,op){
  var mid=String(op&&op._userMessageId||'');if(!mid)return null;
  var row=null;try{row=await dbGet('apiSettings','map_ticket_'+mid)}catch(e){}
  if(!row||(row.status!=='ready'&&row.status!=='writing')||String(row.friendId||'')!==String(cfg&&cfg.id||'')||String(row.threadId||'')!==String(op&&op._threadId||'')||!row.trip)return null;
  return{m:{id:mid},j:0,r:{trip:row.trip},early:false}
};
var _ibMobileTripExec=window.IBMap.tripExec;
window.IBMap.tripExec=async function(cfg,op,ctx){
  ctx=ctx||{};op=Object.assign({},op||{},{_userMessageId:String(ctx.userMessageId||''),_threadId:String(ctx.threadId||'')});
  var mid=op._userMessageId;
  if(!cfg||cfg._group||String(ctx.friendId||'').indexOf('group_')===0)return{type:op.type,ok:false,label:'Map 环球旅行',reason:'群聊里不能启动 Map 环球旅行'};
  if(op.type==='trip'&&!mid)return{type:'trip',ok:false,label:'Map · 出发',reason:'没有用户发起的 Map 旅行附件，这条旅行指令已被拦截'};
  if(op.type==='trip_note'&&String(op.body||'').trim()&&!mid)return{type:'trip_note',ok:false,label:'Map · 游记',reason:'游记必须接在本条 Chat 发起的旅行之后保存'};
  try{return Object.assign({type:op.type},await _ibMobileTripExec(cfg,op,{friendId:String(ctx.friendId||''),threadId:String(ctx.threadId||''),userMessageId:mid})||{ok:false,label:'Map 环球旅行',reason:'旅行没有返回结果'})}
  catch(e){return{type:op.type,ok:false,label:op.type==='trip'?'Map · 出发':'Map · 游记',reason:String(e&&e.message||e).slice(0,160)}}
};
